@r1 syntax.relation marker="on" from=$c1 to=$n2
@n2 syntax.nominal dependent="an" dependent="of" dependent="f" head="page"
@r2 syntax.relation marker="for" from=$c1 to=$n3
@n3 syntax.nominal head="1"

alt:
@n1 syntax.nominal dependent="the" head="ids"
@c1 syntax.clause form=declarative verb="go" modifier="quiet" modifier="on" modifier="an" modifier="just" subject=$n1
@r1 syntax.relation marker="of" from=$c1 to=$n2
@n2 syntax.nominal dependent="f" head="page"
@r2 syntax.relation marker="for" from=$c1 to=$n3
