sop:
@c1 syntax.clause form=imperative verb="flash" modifier="up" complement=$n1
@n1 syntax.nominal dependent="the" dependent="id" head="list"
@r1 syntax.relation attachment=ambiguous marker="as" from=$c1 to=$n2
@n2 syntax.nominal dependent="a" dependent="temporary" head="page"
@n3 syntax.nominal head="duration"
@n4 syntax.nominal head="1"
@k1 syntax.coordination conjunct=$c1 conjunct=$c2
@c2 syntax.clause form=fragment complement=$n3
@r2 syntax.relation from=$n3 to=$n4

